<script setup>definePageMeta({middleware:['auth','admin']});const {data,refresh}=await useFetch('/api/admin/overview');async function approve(id){await $fetch(`/api/admin/users/${id}/approve`,{method:'POST'});refresh()}async function exportCsv(){location.href='/api/admin/export'}</script><template><main class="max-w-7xl mx-auto p-7 space-y-6"><div class="flex justify-between"><div><h1 class="text-3xl font-black">Admin PCI</h1><p>Kelola informasi, target, karyawan, dan pemahaman.</p></div><div class="flex gap-2"><NuxtLink class="btn-primary" to="/admin/cards/new">+ Card</NuxtLink><NuxtLink class="btn bg-white" to="/admin/employees">Karyawan</NuxtLink><button class="btn bg-white" @click="exportCsv">Export CSV</button></div></div><div class="grid md:grid-cols-3 gap-4"><div class="panel"><b>Total card</b><p class="text-3xl">{{data?.stats.cards}}</p></div><div class="panel"><b>Karyawan aktif</b><p class="text-3xl">{{data?.stats.users}}</p></div><div class="panel"><b>Belum selesai</b><p class="text-3xl">{{data?.stats.pending}}</p></div></div><section class="panel"><h2 class="text-xl font-black">Menunggu persetujuan</h2><div v-for="u in data?.pendingUsers" class="flex justify-between border-t py-3"><span>{{u.name}} · {{u.nik}} · {{u.email}}</span><button class="btn-primary" @click="approve(u.id)">Setujui</button></div><p v-if="!data?.pendingUsers.length">Tidak ada.</p></section><section class="panel"><h2 class="text-xl font-black">Monitoring per card</h2><div v-for="c in data?.cards" class="border-t py-3"><div class="flex justify-between"><b>{{c.title}}</b><span>{{c.done_count}}/{{c.target_count}} done</span></div><p class="text-sm text-red-700">Belum baca: {{c.unread_names||'-'}}</p><p class="text-sm text-yellow-700">Belum paham/lulus: {{c.not_understood_names||'-'}}</p></div></section></main></template>